import json,freya
r=json.load(open('results/run2.json'))
for row in r['rows']:
  if row['pass']: continue
  print('=====',row['id']); [print('REASON',f) for f in row['failed']]
  c=freya.get_call(row['call_id'])
  for m in c.get('messages',[]):
    if m.get('role') in ('user','assistant'): print(m['role'],':',m.get('message') or m.get('content'))
    else:
      t=m.get('message') or ''
      if 'function_call_' in t and ('promise' in t): print('  SYS',t[:300])
"
